steps.seedCode:
import { Component, OnInit } from '@angular/core';
import { HttpClient } from '@angular/common/http';

@Component({
  selector: 'app-token-rotation',
  template: ''
})
export class TokenRotationComponent implements OnInit {
  currentToken: string = '';
  newToken: string = '';
  isRotating: boolean = false;

  constructor(private http: HttpClient) {}

  ngOnInit(): void {}

  rotateToken(): void {
    this.isRotating = true;
    this.http.post<{ token: string }>('/api/rotate-token', {}).subscribe({
      next: (response) => {
        this.currentToken = this.newToken;
        this.newToken = response.token;
        this.isRotating = false;
      }
    });
  }
}

